# Numeric roots, bounded analytically. Strict convexity/concavity controls counts.
def root_scan(fn,lo,hi,steps=20000):
 out=[];old=lo;fo=fn(old)
 for j in range(1,steps+1):
  a=lo+(hi-lo)*j/steps;fa=fn(a)
  if fa*fo<0:
   left,right=old,a
   for _ in range(60):
    mid=(left+right)/2
    if fn(left)*fn(mid)<=0:right=mid
    else:left=mid
   z=(left+right)/2
   if not out or abs(z-out[-1])>1e-7:out.append(z)
  old,fo=a,fa
 return out
